import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
            A = []
            for _ in range(N):
                A.append(int(next(iterator)))
        except StopIteration:
            break

        count = {}
        ans = 0
        for x in A:
            if x in count:
                ans += 1
                count[x] += 1
            else:
                count[x] = 1

        print(ans)

if __name__ == "__main__":
    solve()
